352	/// Re-authenticate a created API key credential.
353	///
354	/// The presented value is `base64("id:api_key")`. Decode it, split on the
355	/// first `':'`, look the id up in the engine's key store, and constant-time
356	/// compare the secret. The resulting principal carries the key's stored
357	/// grants: [`Principal::Scoped`] when it was minted with usable
358	/// `role_descriptors`, [`Principal::Unscoped`] otherwise.
359	fn authenticate_api_key(state: &AppState, presented: &str) -> Principal {
360	    let decoded = match crate::es_compat::base64_decode(presented) {
361	        Some(d) => d,
362	        None => return Principal::Denied,
363	    };
364	    let decoded = match std::str::from_utf8(&decoded) {
365	        Ok(s) => s,
366	        Err(_) => return Principal::Denied,
367	    };
368	    let (id, secret) = match decoded.split_once(':') {
369	        Some(parts) => parts,
370	        None => return Principal::Denied,
371	    };
372	    check_minted_key(state, id, secret)
373	}
374	
375	/// Look up a minted `POST /_security/api_key` credential by `(id, secret)`.
376	/// Shared by the `ApiKey <base64(id:secret)>` and `Basic <base64(id:secret)>`
377	/// paths — both decode to the same `id:secret` shape.
378	///
379	/// A minted key is **never** a superuser: the strongest thing it can be is
380	/// `Unscoped`, which has no reach into the reserved `.xerj-memory-*`
381	/// namespace. That is what stops "any authenticated caller reads any brain".
382	fn check_minted_key(state: &AppState, id: &str, secret: &str) -> Principal {
383	    let record = match state.engine.api_keys.get(id) {
384	        Some(r) => r,
385	        None => return Principal::Denied,
386	    };
387	    if record.invalidated {
388	        return Principal::Denied;
389	    }
390	    if let Some(exp) = record.expiration_ms {
391	        let now_ms = chrono::Utc::now().timestamp_millis().max(0) as u64;
392	        if now_ms >= exp {
393	            return Principal::Denied;
394	        }
395	    }
396	    // Issue #201: the stored form is a salted SHA-256 digest, not the
397	    // credential. `verify_secret` hashes the presented secret under the
398	    // record's salt and compares digests in constant time, and answers `false`
399	    // for any record it cannot make sense of — an unmigrated or mangled record
400	    // denies rather than falling back to a plaintext compare.
401	    if !record.verify_secret(secret) {
402	        return Principal::Denied;
403	    }
404	    if record.roles.is_empty() {
405	        Principal::Unscoped {
406	            key_id: id.to_string(),
407	        }
408	    } else {
409	        Principal::Scoped {
410	            key_id: id.to_string(),
411	            roles: record.roles.clone(),
412	        }
413	    }
414	}
415	
416	/// Length-independent-only constant-time byte comparison. Avoids leaking the
417	/// secret via early-exit timing once lengths match.
418	fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
419	    if a.len() != b.len() {
420	        return false;
421	    }
422	    let mut diff = 0u8;
423	    for (x, y) in a.iter().zip(b.iter()) {
424	        diff |= x ^ y;
425	    }
426	    diff == 0
427	}
428	
429	// ─────────────────────────────────────────────────────────────────────────────
430	// Helpers
431	// ─────────────────────────────────────────────────────────────────────────────
432	
433	/// Extract the raw key from an `Authorization` header value.
434	///
435	/// Accepts both `ApiKey <key>` and `Bearer <key>` schemes (case-insensitive
436	/// scheme prefix).
437	fn extract_key(header: &str) -> Option<&str> {
438	    let lower = header.to_ascii_lowercase();
439	    if lower.starts_with("apikey ") {
440	        Some(header["ApiKey ".len()..].trim())
441	    } else if lower.starts_with("bearer ") {
442	        Some(header["Bearer ".len()..].trim())
443	    } else {
444	        None
445	    }
446	}
