456	/// The rate-limit key for a claim source: the address itself for IPv4, the
457	/// enclosing /64 for IPv6. A single IPv6 host is routinely delegated a whole
458	/// /64 and can take a fresh address per request, so per-address buckets there
459	/// are no throttle at all. Anything that is not an address (`unknown`) is its
460	/// own bucket.
461	fn source_bucket(source: &str) -> String {
462	    match source.parse::<IpAddr>() {
463	        Ok(IpAddr::V6(v6)) => {
464	            let mut seg = v6.segments();
465	            seg[4..].fill(0);
466	            format!("{}/64", std::net::Ipv6Addr::from(seg))
467	        }
468	        _ => source.to_string(),
469	    }
470	}
