476	/// A fresh share id: 128 bits from the OS CSPRNG, lowercase hex.
477	fn mint_share_id() -> String {
478	    let mut bytes = [0u8; 16];
479	    rand::rngs::OsRng.fill_bytes(&mut bytes);
480	    hex(&bytes)
481	}
