483	/// `(full sha256 hex, 12-char handle)` for a share id.
484	fn hash_share_id(share_id: &str) -> (String, String) {
485	    let digest = Sha256::digest(share_id.as_bytes());
486	    let full = hex(&digest);
487	    let handle = full[..12].to_string();
488	    (full, handle)
489	}
