696	/// Nothing under `/_share` may be stored by a browser, a proxy or a CDN: the
697	/// create response carries the link and passcode, the claim response carries
698	/// a live credential, and an error body says whether a share exists.
699	/// `no-store` for HTTP/1.1 caches, `Pragma` for the HTTP/1.0 ones still found
700	/// in front of things.
701	pub(crate) fn no_store(mut resp: Response) -> Response {
702	    let headers = resp.headers_mut();
703	    headers.insert(
704	        header::CACHE_CONTROL,
705	        header::HeaderValue::from_static("no-store, max-age=0"),
706	    );
707	    headers.insert(header::PRAGMA, header::HeaderValue::from_static("no-cache"));
