            out.push_str("%H");
            i += 2;
        } else if rest.starts_with("mm") {
            out.push_str("%M");
            i += 2;
        } else if rest.starts_with("ss") {
            out.push_str("%S");
            i += 2;
        } else if rest.starts_with("SSSSSSSSS") {
            out.push_str("%9f");
            i += 9;
        } else if rest.starts_with("SSSSSS") {
            out.push_str("%6f");
            i += 6;
        } else if rest.starts_with("SSS") {
