            i += 3;
        } else if rest.starts_with("ZZZZZ") {
            out.push_str("%:z");
            i += 5;
        } else if rest.starts_with("XXX") {
            out.push_str("%:z");
            i += 3;
        } else if rest.starts_with('Z') {
            out.push_str("%z");
            i += 1;
        } else if rest.starts_with('\'') {
            i += 1;
            while i < bytes.len() && bytes[i] != b'\'' {
